import os
import numpy as np
import multiprocessing as mp


def _eig(indptr, indices, data, n, k):
    from scipy.sparse.linalg._eigen.arpack import arpack as ar
    from scipy.sparse._sparsetools import csr_matvec
    # Same ARPACK (dnaupd/dneupd) computation as scipy.sparse.linalg.eigs with
    # v0=ones, ncv=max(2k+1,20), tol=0, but with a lean reverse-communication loop.
    ncv = max(2 * k + 1, 20)
    P = ar._UnsymmetricArpackParams(n, k, data.dtype.char if data.dtype.char in 'fdFD' else 'd',
                                    None or (lambda x: x), 1, None, None, None,
                                    ncv, np.ones(n, dtype=data.dtype), n * 200, 'LM', 0)
    sol = P._arpack_solver
    d = P.arpack_dict
    resid, v, ip, wd, wl = P.resid, P.v, P.ipntr, P.workd, P.workl
    complex_ = P.tp in 'FD'
    rwork = P.rwork
    while True:
        if complex_:
            sol(d, resid, v, ip, wd, wl, rwork)
        else:
            sol(d, resid, v, ip, wd, wl)
        ido = d['ido']
        if ido == 1 or ido == 5:
            x = ip[0]
            y = ip[1]
            out = wd[y:y + n]
            out[:] = 0
            csr_matvec(n, n, indptr, indices, data, wd[x:x + n], out)
        elif ido == 4:
            # restart vector requested; same as scipy's handling
            if complex_:
                resid[:] = P.rng.uniform(-1.0, 1.0, size=[n, 2]).view(np.complex128).astype(P.tp).ravel()
            else:
                resid[:] = P.rng.uniform(-1.0, 1.0, size=[n]).astype(P.tp)
        elif ido == 99:
            break
        else:
            raise RuntimeError("unexpected ido %d" % ido)
    if d['info'] != 0:
        raise RuntimeError("ARPACK info %d" % d['info'])
    w, vecs = P.extract(True)
    order = sorted(range(len(w)), key=lambda i: -abs(w[i]))
    return [vecs[:, i] for i in order]


def _worker(conn):
    while True:
        msg = conn.recv()
        if msg is None:
            break
        try:
            conn.send((True, _eig(*msg)))
        except Exception as e:
            conn.send((False, repr(e)))


class Solver:
    def __init__(self):
        self._conn = None
        self._proc = None

    def _start(self):
        # Single-threaded BLAS is much faster for these small dense ARPACK ops;
        # Accelerate only reads this at load time, so use a fresh worker process.
        old = os.environ.get("VECLIB_MAXIMUM_THREADS")
        os.environ["VECLIB_MAXIMUM_THREADS"] = "1"
        try:
            ctx = mp.get_context("spawn")
            a, b = ctx.Pipe()
            self._proc = ctx.Process(target=_worker, args=(b,), daemon=True)
            self._proc.start()
            self._conn = a
        finally:
            if old is None:
                os.environ.pop("VECLIB_MAXIMUM_THREADS", None)
            else:
                os.environ["VECLIB_MAXIMUM_THREADS"] = old

    def solve(self, problem, **kwargs):
        A = problem["matrix"].tocsr()
        k = problem["k"]
        n = A.shape[0]
        args = (A.indptr, A.indices, A.data, n, k)
        try:
            if self._proc is None or not self._proc.is_alive():
                self._start()
            self._conn.send(args)
            ok, res = self._conn.recv()
            if ok:
                return res
        except Exception:
            pass
        return _eig(*args)

